update cjams.assessment 
set submissiondata = '{"Q1": "An FTDM was held and family members were contacted in attempt to elminate the need for foster care placement.\nUnfortunately, Ms. Diane Meadows was unwilling to remove her boyfriend, who sexual abused Heaven, from the home so Heaven\nhad to be removed.", "Q2": "The Department searched for Heaven''s family members and has attempted to identify long term foster care placements.\nHeaven has recently transitioned to a ILP placement where she will continue to develop skills around independent living.", "Q3": "The Department has exhausted foster home placements for Heaven as she frequently requests dissatisfaction with her\nplacements. Heaven is now living independently with support of an ILP program.", "Q5": "Consistent contact with the Department has not been made by her family requesting visits or requesting Heaven to be placed\nwith them. Heaven''s mother passed away unexpectedly during in July 2020. Heaven indicated that she wanted to have visits with her maternal aunt; the Agency was able to assist in\ncoordination however her aunt has since stopped wanting to have visits with Heaven.", "Q6": "See above. ", "Q7": "During the past year, Heaven was engaged with an intensive community based therapy program called MST-EA; these services were time-limited and have since been terminated. Heaven is currently engaged with People Encouraging People''s Assertive Community Treatment Team (PEP-ACT) who will provider her support around mental health, substance use, housing, and employment. Heaven has strong support from her CASA and placement provider.  Heaven has also been referred to DORS for employment support. ", "Q9": "This worker meets with Heaven at least once per month and communicates with Heaven''s treatment team and providers on a regular basis to ensure her safety, well-being, and permanency. The Department continues to explore long-term supports which may be appropriate for Heaven following her 21st birthday. ", "Q10": "Heaven is receiving services through PEP-ACT and DORS who will provide her with support in developing independent skills. Heaven''s ILP placement provides independent living skills education groups. ", "Q12": "Due to Heaven''s significant mental health concerns, the Department is exploring the appropriateness of supportive living arrangements. Heaven will need to obtain stable housing and employment after her DSS case closes; she may require additional support. ", "Q81": 1, "Q456": 1, "QIII": [{"panel8479878736818369DataGridColumnsName": "Jerica Blue", "panel8479878736818369DataGridColumnsRelationship": "Case Manager", "panel8479878736818369DataGridColumnsNatureOfSupport": "Emotional and professional "}, {"panel8479878736818369DataGridColumnsName": "Helene Hill", "panel8479878736818369DataGridColumnsRelationship": "CASA", "panel8479878736818369DataGridColumnsNatureOfSupport": "Emotional"}], "child": {"age": "20 Yrs", "dob": "2000-12-30T05:00:00.000Z", "prefx": null, "gender": "Female", "suffix": null, "cjamspid": "1436792", "fullname": "HEAVEN  OXENDINE ", "lastname": "OXENDINE", "personid": "37218c78-d72c-46fd-81f5-e48c2cbbf211", "firstname": "HEAVEN", "clientname": "Heaven Oxendine", "middlename": "", "placements": [{"county": null, "old_id": "612479", "reason": null, "enddate": "2015-12-30T00:00:00", "endtime": null, "remarks": null, "zipcode": 21204, "address1": "6501", "address2": "N. Charles  ST", "cityname": "Towson ", "isvoided": null, "personid": "37218c78-d72c-46fd-81f5-e48c2cbbf211", "voiddate": null, "partnerid": "00000000-0000-0000-0000-000000000000", "startdate": "2015-12-21T00:00:00", "starttime": null, "statename": "Maryland", "workphone": null, "isEditable": false, "providerid": null, "service_id": null, "alternateid": 1542908, "exittypekey": null, "placementid": "945301cc-d520-48e7-84de-753fbd107f0f", "programname": null, "voidremarks": null, "contactphone": "4109383600", "providerdesc": null, "rejectreason": null, "statetypekey": "MD", "comarratedesc": null, "cou